def parse_json(raw_data):
    ''' this version for module return data only '''

    orig_data = raw_data

    # ignore stuff like tcgetattr spewage or other warnings
    data = filter_leading_non_json_lines(raw_data)

    try:
        return json.loads(data)
    except:
        # not JSON, but try "Baby JSON" which allows many of our modules to not
        # require JSON and makes writing modules in bash much simpler
        results = {}
        try:
            tokens = shlex.split(data)
        except:
            print "failed to parse json: "+ data
            raise

        for t in tokens:
            if "=" not in t:
                raise errors.AnsibleError("failed to parse: %s" % orig_data)
            (key,value) = t.split("=", 1)
            if key == 'changed' or 'failed':
                if value.lower() in [ 'true', '1' ]:
                    value = True
                elif value.lower() in [ 'false', '0' ]:
                    value = False
            if key == 'rc':
                value = int(value)
            results[key] = value
        if len(results.keys()) == 0:
            return { "failed" : True, "parsed" : False, "msg" : orig_data }
        return results

def download_check_files(self, filelist):
    # only admins and allowed users may download
    if not cherrypy.session['admin']:
        uo = self.useroptions.forUser(self.getUserId())
        if not uo.getOptionValue('media.may_download'):
            return 'not_permitted'
    # make sure nobody tries to escape from basedir
    for f in filelist:
        if '/../' in f:
            return 'invalid_file'
    # make sure all files are smaller than maximum download size
    size_limit = cherry.config['media.maximum_download_size']
    try:
        if self.model.file_size_within_limit(filelist, size_limit):
            return 'ok'
        else:
            return 'too_big'
    except OSError as e:        # use OSError for python2 compatibility
        return str(e)

def _create_dirs(self):
    """Create folder storing the collection if absent."""
    if not os.path.exists(os.path.dirname(self._path)):
        os.makedirs(os.path.dirname(self._path))

def text(self):
    components = (
        ical.Timezone, ical.Event, ical.Todo, ical.Journal, ical.Card)
    items = set()
    try:
        filenames = os.listdir(self._path)
    except (OSError, IOError) as e:
        log.LOGGER.info('Error while reading collection %r: %r'
                        % (self._path, e))
        return ""

    for filename in filenames:
        path = os.path.join(self._path, filename)
        try:
            with filesystem.open(path) as fd:
                items.update(self._parse(fd.read(), components))
        except (OSError, IOError) as e:
            log.LOGGER.warning('Error while reading item %r: %r'
                               % (path, e))

    return ical.serialize(
        self.tag, self.headers, sorted(items, key=lambda x: x.name))

