async def test_info_and_warning_alerts(self):
    def greet(s):
        for _c in s:
            gr.Info(f"Letter {_c}")
            time.sleep(0.15)
        if len(s) < 5:
            gr.Warning("Too short!")
        return f"Hello, {s}!"

    demo = gr.Interface(greet, "text", "text")
    demo.queue().launch(prevent_thread_lock=True)

    log_messages = []
    async with httpx.AsyncClient() as client:
        async with client.stream(
            "GET",
            f"http://localhost:{demo.server_port}/queue/join",
            params={"fn_index": 0, "session_hash": "shdce"},
        ) as response:
            async for line in response.aiter_text():
                if line.startswith("data:"):
                    msg = json.loads(line[5:])
                if msg["msg"] == "send_data":
                    event_id = msg["event_id"]
                    req = await client.post(
                        f"http://localhost:{demo.server_port}/queue/data",
                        json={
                            "event_id": event_id,
                            "data": ["abc"],
                            "fn_index": 0,
                        },
                    )
                    if not req.is_success:
                        raise ValueError(
                            f"Could not send payload to endpoint: {req.text}"
                        )
                if msg["msg"] == "log":
                    log_messages.append([msg["log"], msg["level"]])
                if msg["msg"] == "process_completed":
                    break

    assert log_messages == [
        ["Letter a", "info"],
        ["Letter b", "info"],
        ["Letter c", "info"],
        ["Too short!", "warning"],
    ]

def generate_subparsers(root, parent_parser, definitions):
    action_dest = '_'.join(parent_parser.prog.split()[1:] + ['action'])
    actions = parent_parser.add_subparsers(
        dest=action_dest
    )
    for command, properties in definitions.items():
        is_subparser = isinstance(properties, dict)
        descr = properties.pop('help', None) if is_subparser else properties.pop(0)
        command_parser = actions.add_parser(command, description=descr)
        command_parser.root = root
        if is_subparser:
            generate_subparsers(root, command_parser, properties)
            continue

        for argument in properties:
            command_parser.add_argument(**argument)

def _validate_source(source: str, run_id: str) -> None:
    if not is_local_uri(source):
        return

    if run_id:
        store = _get_tracking_store()
        run = store.get_run(run_id)
        source = pathlib.Path(local_file_uri_to_path(source)).resolve()
        run_artifact_dir = pathlib.Path(local_file_uri_to_path(run.info.artifact_uri)).resolve()
        if run_artifact_dir in [source, *source.parents]:
            return

    raise MlflowException(
        f"Invalid source: '{source}'. To use a local path as source, the run_id request parameter "
        "has to be specified and the local path has to be contained within the artifact directory "
        "of the run specified by the run_id.",
        INVALID_PARAMETER_VALUE,
    )

