def innerfn(fn):
	global whitelisted, guest_methods, xss_safe_methods, allowed_http_methods_for_whitelisted_func
	whitelisted.append(fn)

	allowed_http_methods_for_whitelisted_func[fn] = methods

	if allow_guest:
