def load_event(self, args, filename, from_misp, stix_version):
    self.outputname = '{}.json'.format(filename)
    if len(args) > 0 and args[0]:
        self.add_original_file(filename, args[0], stix_version)
    try:
        event_distribution = args[1]
        if not isinstance(event_distribution, int):
            event_distribution = int(event_distribution) if event_distribution.isdigit() else 5
    except IndexError:
        event_distribution = 5
    try:
        attribute_distribution = args[2]
        if attribute_distribution == 'event':
            attribute_distribution = event_distribution
        elif not isinstance(attribute_distribution, int):
            attribute_distribution = int(attribute_distribution) if attribute_distribution.isdigit() else event_distribution
    except IndexError:
        attribute_distribution = event_distribution
    self.misp_event.distribution = event_distribution
    self.__attribute_distribution = attribute_distribution
    self.from_misp = from_misp
    self.load_mapping()

def index():
    """ Index handler """

    send = request.vars.send
    if DEMO_MODE:
        session.authorized = True
        session.last_time = t0
    if not send:
        send = URL('site')
    if session.authorized:
        redirect(send)
    elif failed_login_count() >= allowed_number_of_attempts:
        time.sleep(2 ** allowed_number_of_attempts)
        raise HTTP(403)
    elif request.vars.password:
        if verify_password(request.vars.password[:1024]):
            session.authorized = True
            login_record(True)

            if CHECK_VERSION:
                session.check_version = True
            else:
                session.check_version = False

            session.last_time = t0
            if isinstance(send, list):  # ## why does this happen?
                send = str(send[0])

            redirect(send)
        else:
            times_denied = login_record(False)
            if times_denied >= allowed_number_of_attempts:
                response.flash = \
                    T('admin disabled because too many invalid login attempts')
            elif times_denied == allowed_number_of_attempts - 1:
                response.flash = \
                    T('You have one more login attempt before you are locked out')
            else:
                response.flash = T('invalid password.')
    return dict(send=send)

