def login():
    api = flask.current_app.config["PYLOAD_API"]

    next = get_redirect_url(fallback=flask.url_for("app.dashboard"))

    if flask.request.method == "POST":
        user = flask.request.form["username"]
        password = flask.request.form["password"]
        user_info = api.check_auth(user, password)

        if not user_info:
            log.error(f"Login failed for user '{user}'")
            return render_template("login.html", next=next, errors=True)

        set_session(user_info)
        log.info(f"User '{user}' successfully logged in")
        flask.flash("Logged in successfully")

    if is_authenticated():
        return flask.redirect(next)

    if api.get_config_value("webui", "autologin"):
        allusers = api.get_all_userdata()
        if len(allusers) == 1:  # TODO: check if localhost
            user_info = list(allusers.values())[0]
            set_session(user_info)
            # NOTE: Double-check authentication here because if session[name] is empty,
            #       next login_required redirects here again and all loop out.
            if is_authenticated():
                return flask.redirect(next)

    return render_template("login.html", next=next)

def render(self, record, value):  # pylint: disable=arguments-differ
    if value:
        url = reverse(self.viewname, kwargs=self.view_kwargs)
        if self.url_params:
            url += "?" + "&".join([f"{k}={getattr(record, v)}" for k, v in self.url_params.items()])
        return mark_safe(f'<a href="{url}">{value}</a>')
    return value

def post(self, request, pk):
    virtual_chassis = get_object_or_404(self.queryset, pk=pk)

    member_select_form = forms.VCMemberSelectForm(request.POST)

    if member_select_form.is_valid():
        device = member_select_form.cleaned_data["device"]
        device.virtual_chassis = virtual_chassis
        data = {k: request.POST[k] for k in ["vc_position", "vc_priority"]}
        membership_form = forms.DeviceVCMembershipForm(data=data, validate_vc_position=True, instance=device)

        if membership_form.is_valid():
            membership_form.save()
            msg = f'Added member <a href="{device.get_absolute_url()}">{escape(device)}</a>'
            messages.success(request, mark_safe(msg))

            if "_addanother" in request.POST:
                return redirect(request.get_full_path())

            return redirect(self.get_return_url(request, device))

    else:
        membership_form = forms.DeviceVCMembershipForm(data=request.POST)

    return render(
        request,
        "dcim/virtualchassis_add_member.html",
        {
            "virtual_chassis": virtual_chassis,
            "member_select_form": member_select_form,
            "membership_form": membership_form,
            "return_url": self.get_return_url(request, virtual_chassis),
        },
    )

def get(self, request, pk=None):
    instance = get_object_or_404(self.queryset.restrict(request.user, "view"), pk=pk)
    filter_q = request.GET.get("q")
    if filter_q:
        queryset = instance.job_log_entries.filter(
            Q(message__icontains=filter_q) | Q(log_level__icontains=filter_q)
        )
    else:
        queryset = instance.job_log_entries.all()
    log_table = tables.JobLogEntryTable(data=queryset, user=request.user)
    RequestConfig(request).configure(log_table)
    return HttpResponse(log_table.as_html(request))

