async def _handle(self, request: Request) -> StreamResponse:
    rel_url = request.match_info["filename"]
    try:
        filename = Path(rel_url)
        if filename.anchor:
            # rel_url is an absolute name like
            # /static/\\machine_name\c$ or /static/D:\path
            # where the static dir is totally different
            raise HTTPForbidden()
        filepath = self._directory.joinpath(filename).resolve()
        if not self._follow_symlinks:
            filepath.relative_to(self._directory)
    except (ValueError, FileNotFoundError) as error:
        # relatively safe
        raise HTTPNotFound() from error
    except HTTPForbidden:
        raise
    except Exception as error:
        # perm error or other kind!
        request.app.logger.exception(error)
        raise HTTPNotFound() from error

    # on opening a dir, load its contents if allowed
    if filepath.is_dir():
        if self._show_index:
            try:
                return Response(
                    text=self._directory_as_html(filepath), content_type="text/html"
                )
            except PermissionError:
                raise HTTPForbidden()
        else:
            raise HTTPForbidden()
    elif filepath.is_file():
        return FileResponse(filepath, chunk_size=self._chunk_size)
    else:
        raise HTTPNotFound

def decode(self, data: bytes) -> bytes:
    """Decodes data.

    Decoding is done according the specified Content-Encoding
    or Content-Transfer-Encoding headers value.
    """
    if CONTENT_TRANSFER_ENCODING in self.headers:
        data = self._decode_content_transfer(data)
    if CONTENT_ENCODING in self.headers:
        return self._decode_content(data)
    return data

def _get_boundary(self) -> str:
    mimetype = parse_mimetype(self.headers[CONTENT_TYPE])

    assert mimetype.type == "multipart", "multipart/* content type expected"

    if "boundary" not in mimetype.parameters:
        raise ValueError(
            "boundary missed for Content-Type: %s" % self.headers[CONTENT_TYPE]
        )

    boundary = mimetype.parameters["boundary"]
    if len(boundary) > 70:
        raise ValueError("boundary %r is too long (70 chars max)" % boundary)

    return boundary

async def handle_404(request, response):
    if 'json' not in response.headers['Content-Type']:
        if request.path.endswith('/'):
            return web.HTTPFound(request.path.rstrip('/'))
        return web.json_response({
            "status": 404,
            "message": "Page '{}' not found".format(request.path)
        }, status=404)
    return response

async def handle_404(request, response):
