def login():
    from flask_login import current_user

    redirect_url = request.args.get("redirect", request.script_root + url_for("index"))
    permissions = sorted(
        filter(
            lambda x: x is not None and isinstance(x, OctoPrintPermission),
            map(
                lambda x: getattr(Permissions, x.strip()),
                request.args.get("permissions", "").split(","),
            ),
        ),
        key=lambda x: x.get_name(),
    )
    if not permissions:
        permissions = [Permissions.STATUS, Permissions.SETTINGS_READ]

    user_id = request.args.get("user_id", "")

    if (not user_id or current_user.get_id() == user_id) and has_permissions(
        *permissions
    ):
        return redirect(redirect_url)

    render_kwargs = {
        "theming": [],
        "redirect_url": redirect_url,
        "permission_names": map(lambda x: x.get_name(), permissions),
        "user_id": user_id,
        "logged_in": not current_user.is_anonymous,
    }

    try:
        additional_assets = _add_additional_assets("octoprint.theming.login")

        # backwards compatibility to forcelogin & loginui plugins which were replaced by this built-in dialog
        additional_assets += _add_additional_assets("octoprint.plugin.forcelogin.theming")
        additional_assets += _add_additional_assets("octoprint.plugin.loginui.theming")

        render_kwargs.update({"theming": additional_assets})
    except Exception:
        _logger.exception("Error processing theming CSS, ignoring")

    return render_template("login.jinja2", **render_kwargs)

def cookies(self):
    # strip cookie_suffix from all cookies in the request, return result
    cookies = flask.Request.cookies.__get__(self)

    result = {}
    desuffixed = {}
    for key, value in cookies.items():
        if key.endswith(self.cookie_suffix):
            desuffixed[key[: -len(self.cookie_suffix)]] = value
        else:
            result[key] = value

    result.update(desuffixed)
    return result

def get_share_link(recipe):
    url = recipe.storage.url + '/ocs/v2.php/apps/files_sharing/api/v1/shares?format=json&path=' + recipe.file_path  # noqa: E501

    headers = {
        "OCS-APIRequest": "true",
        "Content-Type": "application/json"
    }

    r = requests.get(
        url,
        headers=headers,
        auth=HTTPBasicAuth(
            recipe.storage.username, recipe.storage.password
        )
    )

    response_json = r.json()
    for element in response_json['ocs']['data']:
        if element['share_type'] == '3':
            return element['url']

    return Nextcloud.create_share_link(recipe)

def _checkpassword(realm, username, password):
    """
    Check basic authentication.
    """
    # Validate username
    userobj = UserObject.get_user(username)
    if userobj is not None:
        # Verify if the password matches a token.
        if userobj.validate_access_token(password):
            return True
        # Disable password authentication for MFA
        if userobj.mfa == UserObject.ENABLED_MFA:
            return False
    # Otherwise validate username password
    return any(cherrypy.engine.publish('login', username, password))

