def __init__(self, formats=None, content_types=None, datetime_formatting=None):
    self.supported_formats = []
    self.datetime_formatting = getattr(settings, 'TASTYPIE_DATETIME_FORMATTING', 'iso-8601')

    if formats is not None:
        self.formats = formats

    if content_types is not None:
        self.content_types = content_types

    if datetime_formatting is not None:
        self.datetime_formatting = datetime_formatting

    for format in self.formats:
        try:
            self.supported_formats.append(self.content_types[format])
        except KeyError:
            raise ImproperlyConfigured("Content type for specified type '%s' not found. Please provide it at either the class level or via the arguments." % format)

def get_multi(self, keys, server_key):
    """
    Gets multiple values from memcache for the given keys.

    :param keys: keys for values to be retrieved from memcache
    :param servery_key: key to use in determining which server in the ring
                        is used
    :returns: list of values
    """
    server_key = md5hash(server_key)
    keys = [md5hash(key) for key in keys]
    for (server, fp, sock) in self._get_conns(server_key):
        try:
            sock.sendall('get %s\r\n' % ' '.join(keys))
            line = fp.readline().strip().split()
            responses = {}
            while line[0].upper() != 'END':
                if line[0].upper() == 'VALUE':
                    size = int(line[3])
                    value = fp.read(size)
                    if int(line[2]) & PICKLE_FLAG:
                        value = pickle.loads(value)
                    responses[line[1]] = value
                    fp.readline()
                line = fp.readline().strip().split()
            values = []
            for key in keys:
                if key in responses:
                    values.append(responses[key])
                else:
                    values.append(None)
            self._return_conn(server, fp, sock)
            return values
        except Exception, e:
            self._exception_occurred(server, e)

def delete(self, location, connection=None):
    location = location.store_location
    if not connection:
        connection = self.get_connection(location)

    try:
        # We request the manifest for the object. If one exists,
        # that means the object was uploaded in chunks/segments,
        # and we need to delete all the chunks as well as the
        # manifest.
        manifest = None
        try:
            headers = connection.head_object(
                    location.container, location.obj)
            manifest = headers.get('x-object-manifest')
        except swiftclient.ClientException, e:
            if e.http_status != httplib.NOT_FOUND:
                raise
        if manifest:
            # Delete all the chunks before the object manifest itself
            obj_container, obj_prefix = manifest.split('/', 1)
            segments = connection.get_container(
                    obj_container, prefix=obj_prefix)[1]
            for segment in segments:
                # TODO(jaypipes): This would be an easy area to parallelize
                # since we're simply sending off parallelizable requests
                # to Swift to delete stuff. It's not like we're going to
                # be hogging up network or file I/O here...
                connection.delete_object(
                        obj_container, segment['name'])

        else:
            connection.delete_object(location.container, location.obj)

    except swiftclient.ClientException, e:
        if e.http_status == httplib.NOT_FOUND:
            uri = location.get_uri()
            raise exception.NotFound(_("Swift could not find image at "
                                       "uri %(uri)s") % locals())
        else:
            raise

