def login(self, flag=True) -> WerkzeugResponse:
    @self.appbuilder.sm.oid.loginhandler
    def login_handler(self):
        if g.user is not None and g.user.is_authenticated:
            return redirect(self.appbuilder.get_url_for_index)
        form = LoginForm_oid()
        if form.validate_on_submit():
            session["remember_me"] = form.remember_me.data
            return self.appbuilder.sm.oid.try_login(
                form.openid.data,
                ask_for=self.oid_ask_for,
                ask_for_optional=self.oid_ask_for_optional,
            )
        return self.render_template(
            self.login_template,
            title=self.title,
            form=form,
            providers=self.appbuilder.sm.openid_providers,
            appbuilder=self.appbuilder,
        )

    @self.appbuilder.sm.oid.after_login
    def after_login(resp):
        if resp.email is None or resp.email == "":
            flash(as_unicode(self.invalid_login_message), "warning")
            return redirect(self.appbuilder.get_url_for_login)
        user = self.appbuilder.sm.auth_user_oid(resp.email)
        if user is None:
            flash(as_unicode(self.invalid_login_message), "warning")
            return redirect(self.appbuilder.get_url_for_login)
        remember_me = False
        if "remember_me" in session:
            remember_me = session["remember_me"]
            session.pop("remember_me", None)

        login_user(user, remember=remember_me)
        next_url = request.args.get("next", "")
        return redirect(get_safe_redirect(next_url))

    return login_handler(self)

def make_predict(self, helper: Communicator | None = None):
    def _predict(*data) -> tuple:
        data = {
            "data": data,
            "fn_index": self.fn_index,
            "session_hash": self.client.session_hash,
        }

        hash_data = {
            "fn_index": self.fn_index,
            "session_hash": self.client.session_hash,
        }

        result = utils.synchronize_async(self._sse_fn, data, hash_data, helper)
        if "error" in result:
            raise ValueError(result["error"])

        try:
            output = result["data"]
        except KeyError as ke:
            is_public_space = (
                self.client.space_id
                and not huggingface_hub.space_info(self.client.space_id).private
            )
            if "error" in result and "429" in result["error"] and is_public_space:
                raise utils.TooManyRequestsError(
                    f"Too many requests to the API, please try again later. To avoid being rate-limited, "
                    f"please duplicate the Space using Client.duplicate({self.client.space_id}) "
                    f"and pass in your Hugging Face token."
                ) from None
            elif "error" in result:
                raise ValueError(result["error"]) from None
            raise KeyError(
                f"Could not find 'data' key in response. Response received: {result}"
            ) from ke
        return tuple(output)

    return _predict

