def cookies(self, jar: RequestsCookieJar):
    # <https://docs.python.org/3/library/cookielib.html#cookie-objects>
    stored_attrs = ['value', 'path', 'secure', 'expires']
    self['cookies'] = {}
    for cookie in jar:
        self['cookies'][cookie.name] = {
            attname: getattr(cookie, attname)
