def _iterate_over_text(
    tree: "etree.Element", *tags_to_ignore: Union[str, "etree.Comment"]
) -> Generator[str, None, None]:
    """Iterate over the tree returning text nodes in a depth first fashion,
    skipping text nodes inside certain tags.
    """
    # This is basically a stack that we extend using itertools.chain.
    # This will either consist of an element to iterate over *or* a string
    # to be returned.
    elements = iter([tree])
    while True:
        el = next(elements, None)
        if el is None:
            return

        if isinstance(el, str):
            yield el
        elif el.tag not in tags_to_ignore:
            # If the element isn't meant for display, ignore it.
            if el.get("role") in ARIA_ROLES_TO_IGNORE:
                continue

            # el.text is the text before the first child, so we can immediately
            # return it if the text exists.
            if el.text:
                yield el.text

            # We add to the stack all the elements children, interspersed with
            # each child's tail text (if it exists). The tail text of a node
            # is text that comes *after* the node, so we always include it even
            # if we ignore the child node.
            elements = itertools.chain(
                itertools.chain.from_iterable(  # Basically a flatmap
                    [child, child.tail] if child.tail else [child]
                    for child in el.iterchildren()
                ),
                elements,
            )

def test_visitor(self):
    class CustomVisitor(self.asdl.VisitorBase):
        def __init__(self):
            super().__init__()
            self.names_with_seq = []

        def visitModule(self, mod):
            for dfn in mod.dfns:
                self.visit(dfn)

        def visitType(self, type):
            self.visit(type.value)

        def visitSum(self, sum):
            for t in sum.types:
                self.visit(t)

        def visitConstructor(self, cons):
            for f in cons.fields:
                if f.seq:
                    self.names_with_seq.append(cons.name)

    v = CustomVisitor()
    v.visit(self.types['mod'])
    self.assertEqual(v.names_with_seq, ['Module', 'Interactive', 'Suite'])

