def skip(self, type):
    if type == TType.STOP:
        return
    elif type == TType.BOOL:
        self.readBool()
    elif type == TType.BYTE:
        self.readByte()
    elif type == TType.I16:
        self.readI16()
    elif type == TType.I32:
        self.readI32()
    elif type == TType.I64:
        self.readI64()
    elif type == TType.DOUBLE:
        self.readDouble()
    elif type == TType.FLOAT:
        self.readFloat()
