        self.readI16()
    elif type == TType.I32:
        self.readI32()
    elif type == TType.I64:
        self.readI64()
    elif type == TType.DOUBLE:
        self.readDouble()
    elif type == TType.FLOAT:
        self.readFloat()
    elif type == TType.STRING:
        self.readString()
    elif type == TType.STRUCT:
        name = self.readStructBegin()
        while True:
            (name, type, id) = self.readFieldBegin()
            if type == TType.STOP:
