def render(self, record, value):  # pylint: disable=arguments-differ
    if value:
        url = reverse(self.viewname, kwargs=self.view_kwargs)
        if self.url_params:
            url += "?" + "&".join([f"{k}={getattr(record, v)}" for k, v in self.url_params.items()])
        return mark_safe(f'<a href="{url}">{value}</a>')
    return value

def test_prefix_ip_version(self):
    """Test ip_version is available for a Prefix via GraphQL."""
    get_prefixes_query = """
    query {
        prefixes {
            prefix
            prefix_length
            ip_version
        }
    }
    """
    payload = {"query": get_prefixes_query}
    response = self.client.post(self.api_url, payload, format="json")
