def uniq(inpt):
    output = []
    inpt = [ " ".join(inp.split()) for inp in inpt]
    for x in inpt:
        if x not in output:
            output.append(x)
    return output

def format_runtime(runtime):
    retVal = ""
    if runtime.days:
        retVal = format_unit(runtime.days, 'duration-day', length="long", locale=get_locale()) + ', '
    mins, seconds = divmod(runtime.seconds, 60)
    hours, minutes = divmod(mins, 60)
    # ToDo: locale.number_symbols._data['timeSeparator'] -> localize time separator ?
    if hours:
        retVal += '{:d}:{:02d}:{:02d}s'.format(hours, minutes, seconds)
    elif minutes:
        retVal += '{:2d}:{:02d}s'.format(minutes, seconds)
    else:
        retVal += '{:2d}s'.format(seconds)
    return retVal

async def message(self, ctx, *, message: str):
    """Set the message that is shown at the start of each ticket channel.\n\nUse ``{user.mention}`` to mention the person who created the ticket."""
    try:
        message.format(user=ctx.author)
        await self.config.guild(ctx.guild).message.set(message)
        await ctx.send(f"The message has been set to `{message}`.")
    except KeyError:
        await ctx.send(
            "Setting the message failed. Please make sure to only use supported variables in  `\{\}`"
        )

def __init__(self, cfg, **kwargs):
    self.vpns = cfg.vpns

    if kwargs.get('vpn_id'):
        vpn = self.vpns[kwargs['vpn_id']]
        self._socket_connect(vpn)
        if vpn['socket_connected']:
            release = self.send_command('version\n')
            version = semver(self.parse_version(release).split(' ')[1])
            if version.major == 2 and \
                    version.minor >= 4 and \
                    kwargs.get('client_id'):
                command = 'client-kill {0!s}\n'.format(kwargs['client_id'])
            else:
                command = 'kill {0!s}:{1!s}\n'.format(kwargs['ip'], kwargs['port'])
            self.send_command(command)
            self._socket_disconnect()

    geoip_data = cfg.settings['geoip_data']
    self.geoip_version = None
    self.gi = None
    try:
        if geoip_data.endswith('.mmdb') and geoip2_available:
            self.gi = database.Reader(geoip_data)
            self.geoip_version = 2
        elif geoip_data.endswith('.dat') and geoip1_available:
            self.gi = geoip1.open(geoip_data, geoip1.GEOIP_STANDARD)
            self.geoip_version = 1
        else:
            warning('No compatible geoip1 or geoip2 data/libraries found.')
    except IOError:
        warning('No compatible geoip1 or geoip2 data/libraries found.')

    for _, vpn in list(self.vpns.items()):
        self._socket_connect(vpn)
        if vpn['socket_connected']:
            self.collect_data(vpn)
            self._socket_disconnect()

