def run_query(self, query, user):
    path = ""
    ua = ""
    args = {}
    try:
        args = yaml.safe_load(query)
        path = args['url']
        args.pop('url', None)
        ua = args['user-agent']
        args.pop('user-agent', None)

        if is_private_address(path) and settings.ENFORCE_PRIVATE_ADDRESS_BLOCK:
            raise Exception("Can't query private addresses.")
    except:
        pass

    try:
        response = requests.get(url=path, headers={"User-agent": ua})
        workbook = pd.read_csv(io.BytesIO(response.content),sep=",", **args)

        df = workbook.copy()
        data = {'columns': [], 'rows': []}
        conversions = [
            {'pandas_type': np.integer, 'redash_type': 'integer',},
            {'pandas_type': np.inexact, 'redash_type': 'float',},
            {'pandas_type': np.datetime64, 'redash_type': 'datetime', 'to_redash': lambda x: x.strftime('%Y-%m-%d %H:%M:%S')},
            {'pandas_type': np.bool_, 'redash_type': 'boolean'},
            {'pandas_type': np.object, 'redash_type': 'string'}
        ]
        labels = []
        for dtype, label in zip(df.dtypes, df.columns):
            for conversion in conversions:
                if issubclass(dtype.type, conversion['pandas_type']):
                    data['columns'].append({'name': label, 'friendly_name': label, 'type': conversion['redash_type']})
                    labels.append(label)
                    func = conversion.get('to_redash')
                    if func:
                        df[label] = df[label].apply(func)
                    break
        data['rows'] = df[labels].replace({np.nan: None}).to_dict(orient='records')

        json_data = json_dumps(data)
        error = None
    except KeyboardInterrupt:
        error = "Query cancelled by user."
        json_data = None

def send_nscript(title, msg, gtype, force=False, test=None):
    """Run user's notification script"""
    if test:
        script = test.get("nscript_script")
        env = {"notification_parameters": test.get("nscript_parameters")}
    else:
        script = sabnzbd.cfg.nscript_script()
        env = {"notification_parameters": sabnzbd.cfg.nscript_parameters()}

    if not script:
        return T("Cannot send, missing required data")
    title = "SABnzbd: " + T(NOTIFICATION.get(gtype, "other"))

    if force or check_classes(gtype, "nscript"):
        script_path = make_script_path(script)
        if script_path:
            ret = -1
            output = None
            try:
                p = build_and_run_command([script_path, gtype, title, msg], env=create_env(extra_env_fields=env))
                output = p.stdout.read()
                ret = p.wait()
            except:
                logging.info("Failed script %s, Traceback: ", script, exc_info=True)

            if ret:
                logging.error(T('Script returned exit code %s and output "%s"'), ret, output)
                return T('Script returned exit code %s and output "%s"') % (ret, output)
            else:
                logging.info("Successfully executed notification script %s", script_path)
        else:
            return T('Notification script "%s" does not exist') % script_path
    return ""

