        value: file path as a list of strings for each directory level relative to the root.
    Returns:
        tuple of list of files in directory, then list of folders in directory
    """

    def expand_braces(text, seen=None):
        if seen is None:
            seen = set()

        spans = [m.span() for m in re.finditer("{[^{}]*}", text)][::-1]
        alts = [text[start + 1 : stop - 1].split(",") for start, stop in spans]

        if len(spans) == 0:
            if text not in seen:
                yield text
            seen.add(text)

        else:
            for combo in itertools.product(*alts):
                replaced = list(text)
                for (start, stop), replacement in zip(spans, combo):
                    replaced[start:stop] = replacement

                yield from expand_braces("".join(replaced), seen)

    def make_tree(files):
        tree = []
        for file in files:
            parts = file.split(os.path.sep)
            make_node(parts, tree)
        return tree

    def make_node(parts, tree):
        _tree = tree
        for i in range(len(parts)):
            if _tree is None:
                continue
            if i == len(parts) - 1:
                type = "file"
                _tree.append({"path": parts[i], "type": type, "children": None})
                continue
            type = "folder"
            j = next(
                (index for (index, v) in enumerate(_tree) if v["path"] == parts[i]),
                None,
            )
            if j is not None:
                _tree = _tree[j]["children"]
            else:
                _tree.append({"path": parts[i], "type": type, "children": []})
                _tree = _tree[-1]["children"]

def switch_user(request, object_id):

    # current/session user
    current_user = request.user
    session_user = request.session.get("original_user", {"id": current_user.id, "username": current_user.get_username()})

    # check redirect
    redirect_url = request.GET.get("redirect", None)
    if redirect_url is None or not redirect_url.startswith("/"):
        raise Http404()

    # check original_user
    try:
        original_user = User.objects.get(pk=session_user["id"], is_staff=True)
        if not SWITCH_USER_ORIGINAL(original_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(session_user["id"])}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))

    # check new user
    try:
        target_user = User.objects.get(pk=object_id, is_staff=True)
        if target_user != original_user and not SWITCH_USER_TARGET(original_user, target_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(object_id)}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))

    # find backend
    if not hasattr(target_user, 'backend'):
        for backend in settings.AUTHENTICATION_BACKENDS:
            if target_user == load_backend(backend).get_user(target_user.pk):
                target_user.backend = backend
                break

    # target user login, set original as session
    if hasattr(target_user, 'backend'):
        login(request, target_user)
        if original_user.id != target_user.id

def save(self):
    self['__meta__'] = {
        'httpie': __version__
    }
    if self.helpurl:
        self['__meta__']['help'] = self.helpurl

    if self.about:
        self['__meta__']['about'] = self.about

    self.ensure_directory()

    json_string = json.dumps(
        obj=self,
        indent=4,
        sort_keys=True,
        ensure_ascii=True,
    )
    self.path.write_text(json_string + '\n', encoding=UTF8)

def get_cmd(
    model_uri: str, port: int = None, host: int = None, timeout: int = None, nworkers: int = None
) -> Tuple[str, Dict[str, str]]:
    local_uri = path_to_local_file_uri(model_uri)
    timeout = timeout or MLFLOW_SCORING_SERVER_REQUEST_TIMEOUT.get()
    # NB: Absolute windows paths do not work with mlflow apis, use file uri to ensure
    # platform compatibility.
    if os.name != "nt":
        args = [f"--timeout={timeout}"]
        if port and host:
            args.append(f"-b {host}:{port}")
        elif host:
            args.append(f"-b {host}")

        if nworkers:
            args.append(f"-w {nworkers}")

        command = (
            f"gunicorn {' '.join(args)} ${{GUNICORN_CMD_ARGS}}"
            " -- mlflow.pyfunc.scoring_server.wsgi:app"
        )
    else:
        args = []
        if host:
            args.append(f"--host={host}")

        if port:
            args.append(f"--port={port}")

        command = (
            f"waitress-serve {' '.join(args)} "
            "--ident=mlflow mlflow.pyfunc.scoring_server.wsgi:app"
        )

    command_env = os.environ.copy()
    command_env[_SERVER_MODEL_PATH] = local_uri

    return command, command_env

