def test_uses_xdg_config_home(self, apiver):
    with WindowsSafeTempDir() as d:
        account_info = self._make_sqlite_account_info(
            env={
                'HOME': self.home,
                'USERPROFILE': self.home,
                XDG_CONFIG_HOME_ENV_VAR: d,
            }
        )
        if apiver in ['v0', 'v1']:
            expected_path = os.path.abspath(os.path.join(self.home, '.b2_account_info'))
        else:
            assert os.path.exists(os.path.join(d, 'b2'))
            expected_path = os.path.abspath(os.path.join(d, 'b2', 'account_info'))
        actual_path = os.path.abspath(account_info.filename)
        assert expected_path == actual_path

def element():
    element_url = src_url = request.args.get('url')
    if element_url.startswith('gAAAAA'):
        try:
            cipher_suite = Fernet(g.session_key)
            src_url = cipher_suite.decrypt(element_url.encode()).decode()
        except (InvalidSignature, InvalidToken) as e:
            return render_template(
                'error.html',
                error_message=str(e)), 401

    src_type = request.args.get('type')

    try:
        file_data = g.user_request.send(base_url=src_url).content
        tmp_mem = io.BytesIO()
        tmp_mem.write(file_data)
        tmp_mem.seek(0)

        return send_file(tmp_mem, mimetype=src_type)
    except exceptions.RequestException:
        pass

    empty_gif = base64.b64decode(
        'R0lGODlhAQABAIAAAP///////yH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==')
