def parse(self, text):
        """Parse statement/expression to Ast representation."""
        if len(text) > self.max_statement_length:
            msg = f'length of text exceeds {self.max_statement_length:d} characters'
            self.raise_exception(None, exc=RuntimeError, expr=msg)
        self.expr = text
        try:
            out = ast.parse(text)
        except SyntaxError:
            self.raise_exception(None, exc=SyntaxError, expr=text)
        except Exception:
            self.raise_exception(None, exc=RuntimeError, expr=text)
        out = ast.fix_missing_locations(out)
        return out

def get_error(self):
        """Retrieve error data."""
        try:
            exc_name = self.exc.__name__
        except AttributeError:
            exc_name = str(self.exc)
        if exc_name in (None, 'None'):
            exc_name = 'UnknownError'

        out = []
        self.code = [f'{word}' for word  in self.text.split('\n')]
        self.codelines = [f'{i+1}: {word}' for i, word in enumerate(self.code)]

        try:
            out.append('\n'.join(self.code[self.lineno-1:self.end_lineno]))
        except Exception:
            out.append(f"{self.expr}")
        if self.col_offset > 0:
            out.append(f"{self.col_offset*' '}^^^^")
        out.append(f"{exc_name}: {self.msg}")
        return (exc_name, '\n'.join(out))

def ignore_check_source(request: AuthenticatedHttpRequest, check_id):
    obj = get_object_or_404(Check, pk=int(check_id))
    unit = obj.unit.source_unit

    if not request.user.has_perm("unit.check", obj) or not request.user.has_perm(
        "source.edit", unit.translation.component
    ):
        raise PermissionDenied

    # Mark check for ignoring
    if obj.check_obj is None:
        # Disabled check
        ignore = f"ignore-{obj.name.replace('_', '-')}"
    else:
        ignore = obj.check_obj.ignore_string
    flags = Flags(unit.extra_flags)
    if ignore not in flags:
        flags.merge(ignore)
        unit.update_extra_flags(flags.format(), request.user)

    # response for AJAX
    return JsonResponse(
        {
            "extra_flags": unit.extra_flags,
            "all_flags": obj.unit.all_flags.format(),
            "ignore_check": ignore,
        }
    )

def __init__(self, pattern: str):
        self._pattern: str = pattern
        self.priority: int = len(pattern)
        self._contains_asterisk: bool = "*" in self._pattern
        self._contains_dollar: bool = self._pattern.endswith("$")

        if self._contains_asterisk:
            self._pattern_before_asterisk: str = self._pattern[
                : self._pattern.find("*")
            ]
        elif self._contains_dollar:
            self._pattern_before_dollar: str = self._pattern[:-1]

        self._pattern_compiled: re.Pattern[str] | None = None

def __eq__(self, other):
        if len(self.subcomponents) != len(other.subcomponents):
            return False

        properties_equal = super().__eq__(other)
        if not properties_equal:
            return False

        # The subcomponents might not be in the same order,
        # neither there's a natural key we can sort the subcomponents by nor
        # are the subcomponent types hashable, so  we cant put them in a set to
        # check for set equivalence. We have to iterate over the subcomponents
        # and look for each of them in the list.
        for subcomponent in self.subcomponents:
            if subcomponent not in other.subcomponents:
                return False

        # We now know the other component's subcomponents are not a strict subset
        # of this component's. However, we still need to check the other way around.
        for subcomponent in other.subcomponents:
            if subcomponent not in self.subcomponents:
                return False

        return True

