def eval(self, expr, lineno=0, show_errors=True, raise_errors=False):
        """Evaluate a single statement."""
        self.lineno = lineno
        self.error = []
        self.error_msg = None
        self.start_time = time.time()
        if isinstance(expr, str):
            try:
                node = self.parse(expr)
            except Exception:
                errmsg = exc_info()[1]
                if len(self.error) > 0:
                    lerr = self.error[-1]
                    errmsg = lerr.get_error()[1]
                    if raise_errors:
                        raise lerr.exc(errmsg)
                if show_errors:
                    print(errmsg, file=self.err_writer)
                return None
        else:
            node = expr
        try:
            return self.run(node, expr=expr, lineno=lineno, with_raise=raise_errors)
        except Exception:
            if show_errors and not raise_errors:
                errmsg = exc_info()[1]
                if len(self.error) > 0:
                    errmsg = self.error[-1].get_error()[1]
                print(errmsg, file=self.err_writer)
        if raise_errors and len(self.error) > 0:
            self._remove_duplicate_errors()
            err = self.error[-1]
            raise err.exc(err.get_error()[1])
        return None

def _target_to_structure(self, target):
        """Convert AST target to a structure for unpacking (str or nested tuple)"""
        if target.__class__ == ast.Name:
            return target.id
        elif target.__class__ == ast.Tuple:
            return tuple([self._target_to_structure(elt) for elt in target.elts])
        return None

def delete_unit(request: AuthenticatedHttpRequest, unit_id):
    """Delete unit."""
    unit = get_object_or_404(Unit, pk=unit_id)

    if not request.user.has_perm("unit.delete", unit):
        raise PermissionDenied

    try:
        unit.translation.delete_unit(request, unit)
    except WeblateLockTimeoutError:
        messages.error(request, DELETE_UNIT_LOCKED_MESSAGE)
        return redirect(unit)
    except FileParseError as error:
        unit.translation.component.update_import_alerts(delete=False)
        messages.error(request, gettext("Could not remove the string: %s") % error)
        return redirect(unit)
    messages.success(request, gettext("String was removed."))
    # Remove cached search results as we've just removed one of the unit there
    cleanup_session(request.session, delete_all=True)
    return redirect_next(request.POST.get("next"), unit.translation)

def dismiss_automatically_translated(request: AuthenticatedHttpRequest, unit_id):
    unit = get_object_or_404(Unit, pk=int(unit_id))
    if not request.user.has_perm("unit.edit", unit):
        raise PermissionDenied

    unit.translate(
        request.user,
        unit.target,
        unit.state,
        request=request,
    )
    return JsonResponse({})

def __call__(self, environ, start_response):
        req = Request(environ)
        if self.add_slash:
            url = req.path_url
            url += '/'
            if req.environ.get('QUERY_STRING'):
                url += '?' + req.environ['QUERY_STRING']
            self.location = url
        self.location = urlparse.urljoin(req.path_url, self.location)
        return super(_HTTPMove, self).__call__(
            environ, start_response)

async def close(self) -> None:
        """Signal the background task to shut down and wait for it."""
        self.stop_event.set()
        try:
            await asyncio.wait_for(self.task, timeout=_CLOSE_TIMEOUT)
        except asyncio.TimeoutError:
            logger.warning(
                "MCP session %r did not shut down within %.1fs — cancelling",
                self.name,
                _CLOSE_TIMEOUT,
            )
            self.task.cancel()
            try:
