def projects(self, request: Request, **kwargs):
        obj = self.get_object()
        self.perm_check(request, obj)

        if "project_id" not in request.data:
            msg = "Missing project_id parameter"
            raise ValidationError({"project_id": msg})

        field_name = "project_id"
        try:
            project = Project.objects.get(
                pk=int(request.data[field_name]),
            )
        except (TypeError, ValueError) as error:
            raise invalid_integer_error(field_name) from error
        except Project.DoesNotExist as error:
            raise not_found_validation_error(field_name, "Project") from error
        obj.projects.add(project)
        serializer = self.serializer_class(obj, context={"request": request})

        return Response(serializer.data, status=HTTP_200_OK)

def comment(request: AuthenticatedHttpRequest, pk):
    """Add new comment."""
    unit = get_object_or_404(Unit, pk=pk)

    if not request.user.has_perm("comment.add", unit.translation):
        raise PermissionDenied

    form = CommentForm(unit.translation, request.POST)

    if form.is_valid():
        text = form.cleaned_data["comment"]
        scope = form.cleaned_data["scope"]
        Comment.objects.add(request, unit, text, scope)
        messages.success(request, gettext("Posted new comment"))
    else:
        show_form_errors(request, form)
        messages.error(request, gettext("Could not add comment!"))

    return redirect_next(request.POST.get("next"), unit)

