def _host_is_blocked(hostname: str) -> bool:
    """Return True when hostname resolves to loopback/private/internal targets."""
    if not hostname:
        return True
    host = hostname.lower().rstrip(".")
    if host in ("localhost", "0.0.0.0", "::1") or host.endswith(".localhost"):
        return True
    if host in ("169.254.169.254", "metadata.google.internal"):
        return True
    if any(host.endswith(suffix) for suffix in (".local", ".internal", ".localdomain")):
        return True

    def _ip_blocked(ip: ipaddress._BaseAddress) -> bool:
        return bool(
            ip.is_private or ip.is_loopback or ip.is_reserved or ip.is_link_local
        )

    if host.isdigit():
        try:
            return _ip_blocked(ipaddress.ip_address(int(host)))
        except (ValueError, OverflowError):
            return True

    if host.startswith("0x"):
        try:
            return _ip_blocked(ipaddress.ip_address(int(host, 16)))
        except (ValueError, OverflowError):
            return True

    try:
        return _ip_blocked(ipaddress.ip_address(host))
    except ValueError:
        pass

    try:
        return _ip_blocked(ipaddress.ip_address(socket.inet_aton(host)))
    except OSError:
        pass

    return False

def _target_to_structure(self, target):
        """Convert AST target to a structure for unpacking (str or nested tuple)"""
        if target.__class__ == ast.Name:
            return target.id
        elif target.__class__ == ast.Tuple:
            return tuple([self._target_to_structure(elt) for elt in target.elts])
        return None

def resolve_comment(request: AuthenticatedHttpRequest, pk):
    """Resolve comment."""
    comment_obj = get_object_or_404(Comment, pk=pk)

    if not request.user.has_perm("comment.resolve", comment_obj):
        raise PermissionDenied

    fallback_url = comment_obj.unit.get_absolute_url()

    comment_obj.resolve(user=request.user)
    messages.info(request, gettext("Comment has been resolved."))

    return redirect_next(request.POST.get("next"), fallback_url)

